mapper.update:
update CHB_INVESTHOLD_INFO set PRD_REGIST_CODE = #{prdRegistCode,jdbcType=VARCHAR}, STATUS = #{statusToUpdate,jdbcType=VARCHAR} where STATUS = 'A' and (REGIST_BANK_CODE, INDENTIFY_MARK, PRODID, HOLD_DATE, CCY) in ( values
( #{item.registBankCode,jdbcType=VARCHAR}, #{item.indentifyMark,jdbcType=VARCHAR}, #{item.prodid,jdbcType=VARCHAR}, #{item.holdDate,jdbcType=DATE}, #{item.ccy,jdbcType=VARCHAR} )
)

update CHB_INVESTHOLD_INFO set PRD_REGIST_CODE = #{prdRegistCode,jdbcType=VARCHAR} where STATUS = 'E' and (REGIST_BANK_CODE, INDENTIFY_MARK, PRODID, HOLD_DATE, CCY) in ( values
( #{item.registBankCode,jdbcType=VARCHAR}, #{item.indentifyMark,jdbcType=VARCHAR}, #{item.prodid,jdbcType=VARCHAR}, #{item.holdDate,jdbcType=DATE}, #{item.ccy,jdbcType=VARCHAR} )
)

update CHB_INVESTHOLD_INFO_SUB set PRD_REGIST_CODE = #{prdRegistCode,jdbcType=VARCHAR} where STATUS in ('01','02') and (REGIST_BANK_CODE, INDENTIFY_MARK, PRODID, HOLD_DATE, CCY) in ( values
( #{item.registBankCode,jdbcType=VARCHAR}, #{item.indentifyMark,jdbcType=VARCHAR}, #{item.prodid,jdbcType=VARCHAR}, #{item.holdDate,jdbcType=DATE}, #{item.ccy,jdbcType=VARCHAR} )
)

mapper.select:
select T.REGIST_BANK_CODE registBankCode, T.INDENTIFY_MARK indentifyMark, T.PRODID prodid, T.PRD_REGIST_CODE prdRegistCode, T.HOLD_DATE holdDate, T.CCY ccy, T.AMOUNT amount, T.QTY qty, T.CNY_AMT cnyAmt, T.REMARK remark, '' as dataSource, T.STATUS statusCode, T.STATUS status, T.CCY ccyCode, '' as agent, status.SUBMIT_FEEDBACK_MSG as repFailedInfo from CHB_INVESTHOLD_INFO_SUB T left join CHB_SUBMIT_STATUS status on T.sumit_seq = status.seqno
status.SUBMIT_FEEDBACK_STATUS = #{FEEDBACKSTATUS,jdbcType=VARCHAR}
#{SUMIT_SEQ,jdbcType=VARCHAR}
